head.script:
scwin.onpageload = function() {
    // 공통 업무 코드 매핑 객체 초기화
    scwin.itemCodeMap = {
        "01": "기획/전략 수립",
        "02": "화면 설계 및 기획",
        "03": "UI/UX 컴포넌트 개발",
        "04": "백엔드 API 연동",
        "05": "품질 테스트 및 QA",
        "06": "서버 배포 및 모니터링",
        "07": "사용자 매뉴얼 작성"
    };

    // [핵심 요구사항] 메인 페이지 로딩 시 개별 WFrame XML 페이지들을 동적으로 addTab()하여 사전 로딩
    scwin.fn_initDynamicTabs();
};

/**
 * [동적 탭 생성] tac_main.addTab() API를 호출하여 개별 WFrame 페이지들을 동적 생성 및 사전 로딩
 */
scwin.fn_initDynamicTabs = function() {
    var tabConfigs = [
        {
            id: "tab1",
            label: "1. 담당 업무 배정 (메인 그리드)",
            src: "tab1_task_assign.xml",
            closable: false
        },
        {
            id: "tab2",
            label: "2. 프로젝트 팀 현황 (보조 그리드)",
            src: "tab2_team_status.xml",
            closable: false
        },
        {
            id: "tab3",
            label: "3. 공통 코드 설정 및 가이드",
            src: "tab3_guide.xml",
            closable: false
        }
    ];

    tabConfigs.forEach(function(tabInfo, idx) {
        // WebSquare 공식 addTab API 호출
        tac_main.addTab(
            tabInfo.id,
            {
                label: tabInfo.label,
                closable: tabInfo.closable,
                openAction: (idx === 0) ? "select" : "exist",
                alwaysDraw: true // [핵심] 메인 로딩 시 비활성 탭이라도 백그라운드 사전 로딩 완료
            },
            {
                src: tabInfo.src,
                wframe: true
            }
        );
    });
};

// [탭 이동 확인] 비동기 $p.confirm 콜백 후 프로그래밍 탭 이동 허용 플래그
scwin._allowTabChange = false;

/**
 * [탭 변경 확인 헬퍼] 동적으로 생성된 자식 WFrame의 DataList 수정 여부 검사
 * @param {Number} tabIndex - 탭 인덱스 (0, 1, 2)
 * @returns {Boolean} 수정 여부
 */
scwin.fn_isTabModified = function(tabIndex) {
    var frame = tac_main.getFrame(tabIndex);
    if (!frame) return false;

    var win = (typeof frame.getWindow === "function") ? frame.getWindow() : frame;
    if (!win) return false;

    if (tabIndex === 0) {
        // 탭 1 (tab1_task_assign.xml) dlt_sample 변경 확인
        if (win.dlt_sample && typeof win.dlt_sample.getModifiedIndex === "function") {
            return win.dlt_sample.getModifiedIndex().length > 0;
        }
    } else if (tabIndex === 1) {
        // 탭 2 (tab2_team_status.xml) dlt_team 변경 확인
        if (win.dlt_team && typeof win.dlt_team.getModifiedIndex === "function") {
            return win.dlt_team.getModifiedIndex().length > 0;
        }
    }
    return false;
};

/**
 * [요구사항] 탭 변경 전 이벤트 (WebSquare onbeforetabchange)
 */
scwin.tac_main_onbeforetabchange = function(currentTabIndex, newTabIndex) {
    if (scwin._allowTabChange) {
        scwin._allowTabChange = false;
        return true;
    }

    var isModified = scwin.fn_isTabModified(currentTabIndex);
    if (isModified) {
        var tabNames = ["담당 업무 배정", "프로젝트 팀 현황", "공통 코드 설정 및 가이드"];
        var currentTabName = tabNames[currentTabIndex] || "현재 탭";
        var confirmMsg = "[" + currentTabName + "] 탭에 저장되지 않은 변경사항이 있습니다.\n다른 탭으로 이동하시겠습니까?";

        if (window.$p && typeof $p.confirm === "function") {
            $p.confirm(confirmMsg, function(result) {
                if (result) {
                    scwin._allowTabChange = true;
                    tac_main.setSelectedTabIndex(newTabIndex);
                }
            });
        } else {
            if (confirm(confirmMsg)) {
                scwin._allowTabChange = true;
                tac_main.setSelectedTabIndex(newTabIndex);
            }
        }
        return false;
    }

    return true;
};

// 엑셀 다운로드 진행 플래그
scwin._isExcelDownloading = false;

/**
 * [엑셀 다운로드] WebSquare 공식 API (WebSquare.util.multipleExcelDownload) 연동
 */
scwin.btn_excel_onclick = function() {
    scwin._isExcelDownloading = true;

    var rawNotice = (txa_notice.getValue() || "").trim();
    var placeholderText = (typeof txa_notice.getPlaceholder === "function" ? txa_notice.getPlaceholder() : "") || "전달사항을 입력하세요...";
    var hasNotice = (rawNotice !== "" && rawNotice !== placeholderText && rawNotice !== "(입력된 전달사항 없음)" && rawNotice !== "(전달사항 없음)");

    var todayStr = (window.$p && typeof $p.getCurrentServerDate === "function") 
                   ? $p.getCurrentServerDate("yyyyMMdd") 
                   : new Date().toISOString().slice(0, 10).replace(/-/g, "");

    var options = {
        common: {
            fileName: "전체업무현황_WFrame_" + todayStr + ".xlsx",
            showProcess: true,
            multipleSheet: true,
            printGridMargin: 2
        },
        excelFiles: []
    };

    if (hasNotice) {
        options.common.infoArr = [
            {
                rowIndex: 0,
                colIndex: 0,
                rowSpan: 1,
                colSpan: 5,
                text: "■ 공통 전달사항: " + rawNotice,
                textAlign: "left"
            }
        ];
    }

    // 동적 탭 1 WFrame 그리드 추가
    var frame1 = tac_main.getFrame(0);
    var win1 = frame1 ? ((typeof frame1.getWindow === "function") ? frame1.getWindow() : frame1) : null;
    if (win1 && win1.grd_main) {
        options.excelFiles.push({
            gridId: (typeof win1.grd_main.getID === "function") ? win1.grd_main.getID() : win1.grd_main.id,
            sheetName: "담당업무배정",
            useFormat: true
        });
    }

    // 동적 탭 2 WFrame 그리드 추가
    var frame2 = tac_main.getFrame(1);
    var win2 = frame2 ? ((typeof frame2.getWindow === "function") ? frame2.getWindow() : frame2) : null;
    if (win2 && win2.grd_team) {
        options.excelFiles.push({
            gridId: (typeof win2.grd_team.getID === "function") ? win2.grd_team.getID() : win2.grd_team.id,
            sheetName: "프로젝트팀현황",
            useFormat: true
        });
    }

    if (window.WebSquare && window.WebSquare.util && typeof WebSquare.util.multipleExcelDownload === "function") {
        WebSquare.util.multipleExcelDownload(options);
    } else if (window.$p && typeof $p.alert === "function") {
        $p.alert("WebSquare.util.multipleExcelDownload API를 호출하여 동적 탭의 엑셀 다운로드를 실행했습니다.");
    } else {
        alert("엑셀 다운로드가 요청되었습니다.");
    }

    scwin._isExcelDownloading = false;
};

/**
 * [프리뷰] 동적 WFrame 탭들의 데이터를 화면에 보이는 상태 그대로 모달 팝업으로 출력
 */
scwin.btn_preview_onclick = function() {
    var rawNotice = (txa_notice.getValue() || "").trim();
    var placeholderText = (typeof txa_notice.getPlaceholder === "function" ? txa_notice.getPlaceholder() : "") || "전달사항을 입력하세요...";
    var hasNotice = (rawNotice !== "" && rawNotice !== placeholderText && rawNotice !== "(입력된 전달사항 없음)" && rawNotice !== "(전달사항 없음)");

    var noticeBox = document.getElementById("ws_preview_notice_box");
    if (hasNotice) {
        if (noticeBox) noticeBox.style.display = "block";
        var previewNotice = document.getElementById("ws_preview_notice_text");
        if (previewNotice) previewNotice.innerText = rawNotice;
    } else {
        if (noticeBox) noticeBox.style.display = "none";
    }

    // 1. 동적 탭 1 (tab1_task_assign.xml) 데이터 수집 및 렌더링
    var t1Body = document.getElementById("ws_preview_tbl1_body");
    if (t1Body) {
        t1Body.innerHTML = "";
        var frame1 = tac_main.getFrame(0);
        var win1 = frame1 ? ((typeof frame1.getWindow === "function") ? frame1.getWindow() : frame1) : null;
        if (win1 && win1.dlt_sample) {
            var dlt1Data = win1.dlt_sample.getAllJSON();
            for (var i = 0; i < dlt1Data.length; i++) {
                var row = dlt1Data[i];
                var taskHtml = (win1.scwin && typeof win1.scwin.fn_formatMultiCheck === "function") 
                               ? win1.scwin.fn_formatMultiCheck(row.taskCodes) 
                               : (row.taskCodes || "");
                var tr = document.createElement("tr");
                tr.innerHTML = 
                    '<td style="text-align:center; padding:6px; border:1px solid #cbd5e1;">' + (row.seq || "") + '</td>' +
                    '<td style="text-align:center; padding:6px; border:1px solid #cbd5e1; font-weight:500;">' + (row.userName || "") + '</td>' +
                    '<td style="text-align:left; padding:6px; border:1px solid #cbd5e1; line-height:1.5;">' + taskHtml + '</td>' +
                    '<td style="text-align:left; padding:6px; border:1px solid #cbd5e1;">' + (row.remark || "") + '</td>';
                t1Body.appendChild(tr);
            }
        }
    }

    // 2. 동적 탭 2 (tab2_team_status.xml) 데이터 수집 및 렌더링
    var t2Body = document.getElementById("ws_preview_tbl2_body");
    if (t2Body) {
        t2Body.innerHTML = "";
        var frame2 = tac_main.getFrame(1);
        var win2 = frame2 ? ((typeof frame2.getWindow === "function") ? frame2.getWindow() : frame2) : null;
        if (win2 && win2.dlt_team) {
            var dlt2Data = win2.dlt_team.getAllJSON();
            for (var j = 0; j < dlt2Data.length; j++) {
                var r = dlt2Data[j];
                var teamTaskHtml = (win2.scwin && typeof win2.scwin.fn_formatMultiCheck === "function") 
                                   ? win2.scwin.fn_formatMultiCheck(r.taskCodes) 
                                   : (r.taskCodes || "");
                var tr2 = document.createElement("tr");
                tr2.innerHTML = 
                    '<td style="text-align:center; padding:6px; border:1px solid #cbd5e1;">' + (r.seq || "") + '</td>' +
                    '<td style="text-align:left; padding:6px; border:1px solid #cbd5e1; font-weight:500;">' + (r.teamName || "") + '</td>' +
                    '<td style="text-align:center; padding:6px; border:1px solid #cbd5e1;">' + (r.leader || "") + '</td>' +
                    '<td style="text-align:left; padding:6px; border:1px solid #cbd5e1; line-height:1.5;">' + teamTaskHtml + '</td>' +
                    '<td style="text-align:center; padding:6px; border:1px solid #cbd5e1; font-weight:bold; color:#2563eb;">' + (r.progress || "") + '</td>';
                t2Body.appendChild(tr2);
            }
        }
    }

    var modal = document.getElementById("ws_preview_modal_wrap");
    if (modal) modal.style.display = "flex";
};

scwin.fn_closePreviewModal = function() {
    var modal = document.getElementById("ws_preview_modal_wrap");
    if (modal) modal.style.display = "none";
};
